/* ============================================================
   KITE POP — real brand-kite image accents used sparingly
   ============================================================ */
function KitePop({ tone = "amber", size = 64, className = "", style = {}, flip = false }) {
  const [ref, visible] = useReveal();
  const src = tone === "amber" ? kiteAmberImg : kiteWhiteImg;
  return (
    <img
      ref={ref}
      src={src}
      alt=""
      aria-hidden="true"
      className={`kite-pop ${visible ? "kite-pop-in" : ""} ${className}`}
      style={{ width: size, height: "auto", transform: flip ? "scaleX(-1)" : "none", ...style }}
    />
  );
}

/* ============================================================
   LIGHTBOX — click-to-enlarge overlay for infographic images
   ============================================================ */
function Lightbox({ src, alt, onClose }) {
  useEffect(() => {
    if (!src) return;
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
    };
  }, [src, onClose]);

  if (!src) return null;
  return (
    <div className="lightbox" onClick={onClose} role="dialog" aria-modal="true">
      <button className="lightbox-close" onClick={onClose} aria-label="Cerrar">
        <X size={20} />
      </button>
      <img src={src} alt={alt} className="lightbox-img" onClick={(e) => e.stopPropagation()} />
    </div>
  );
}

/* ============================================================
   REVEAL ON SCROLL HOOK
   ============================================================ */
function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            setVisible(true);
            obs.unobserve(e.target);
          }
        });
      },
      { threshold: 0.1 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ as: Tag = "div", delay = 0, className = "", children, ...rest }) {
  const [ref, visible] = useReveal();
  return (
    <Tag ref={ref} className={`reveal ${visible ? "reveal-visible" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }} {...rest}>
      {children}
    </Tag>
  );
}

/* ============================================================
   COUNT UP NUMBER
   ============================================================ */
function CountUp({ target, suffix = "", duration = 1400 }) {
  const [ref, visible] = useReveal();
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!visible) return;
    let start = null;
    let raf;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setVal(Math.floor(eased * target));
      if (progress < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [visible, target, duration]);
  return <span ref={ref} className="stat-number">{val}{suffix}</span>;
}

