/* ============================================================
   NAV — solid, always legible, real logo
   ============================================================ */
function Nav() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  const go = (id) => {
    setOpen(false);
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });
  };
  return (
    <header className={`nav ${scrolled ? "nav-scrolled" : ""}`}>
      <div className="nav-inner">
        <a href="#top" className="nav-logo" onClick={(e) => { e.preventDefault(); go("top"); }}>
          <img src={logoWhiteImg} alt="Kometa — Creatividad + Estrategia" />
        </a>
        <nav className="nav-links">
          {NAV_LINKS.map((l) => (<button key={l.id} onClick={() => go(l.id)}>{l.label}</button>))}
        </nav>
        <a href={SOCIAL.whatsapp} target="_blank" rel="noreferrer" className="nav-cta">
          Empecemos <ArrowUpRight size={16} />
        </a>
        <button className="nav-burger" onClick={() => setOpen((o) => !o)} aria-label="Menú">
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>
      {open && (
        <div className="nav-mobile">
          {NAV_LINKS.map((l) => (<button key={l.id} onClick={() => go(l.id)}>{l.label}</button>))}
          <a href={SOCIAL.whatsapp} target="_blank" rel="noreferrer" className="nav-cta nav-cta-mobile">Empecemos por WhatsApp</a>
        </div>
      )}
    </header>
  );
}

