function SpreadGallery({ images, labels }) {
  const scrollerRef = useRef(null);
  const [paused, setPaused] = useState(false);
  const [lightbox, setLightbox] = useState(null);
  const scrollBy = (dir) => scrollerRef.current?.scrollBy({ left: dir * 520, behavior: "smooth" });

  useEffect(() => {
    if (paused) return;
    const t = setInterval(() => {
      const el = scrollerRef.current;
      if (!el) return;
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 12;
      el.scrollTo({ left: atEnd ? 0 : el.scrollLeft + 360, behavior: "smooth" });
    }, 3200);
    return () => clearInterval(t);
  }, [paused]);

  return (
    <div className="spreads-outer" onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      <div className="spreads-scroller" ref={scrollerRef}>
        {images.map((src, i) => (
          <button
            key={i}
            type="button"
            className="spread-card"
            onClick={() => setLightbox({ src, alt: labels[i] })}
          >
            <img src={src} alt={labels[i]} loading="lazy" />
            <span className="spread-zoom" aria-hidden="true"><Maximize2 size={16} /></span>
            <span className="spread-label">{String(i + 1).padStart(2, "0")} · {labels[i]}</span>
          </button>
        ))}
      </div>
      <div className="spreads-nav">
        <button onClick={() => scrollBy(-1)} aria-label="Anterior"><ChevronLeft size={18} /></button>
        <button onClick={() => scrollBy(1)} aria-label="Siguiente"><ChevronRight size={18} /></button>
      </div>
      <Lightbox src={lightbox?.src} alt={lightbox?.alt} onClose={() => setLightbox(null)} />
    </div>
  );
}

