/* ============================================================
   PORTAFOLIO + CASOS
   ============================================================ */
function Portafolio() {
  const scrollerRef = useRef(null);
  const [paused, setPaused] = useState(false);
  const scrollBy = (dir) => scrollerRef.current?.scrollBy({ left: dir * 360, behavior: "smooth" });

  useEffect(() => {
    if (paused) return;
    const t = setInterval(() => {
      const el = scrollerRef.current;
      if (!el) return;
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 12;
      el.scrollTo({ left: atEnd ? 0 : el.scrollLeft + 340, behavior: "smooth" });
    }, 3400);
    return () => clearInterval(t);
  }, [paused]);

  return (
    <section id="portafolio" className="section section-paper section-pt-tight section-pb-tight">
      <div className="container">
        <Reveal className="section-head" style={{ marginBottom: 40 }}>
          <p className="eyebrow eyebrow-dark">Portafolio</p>
          <h2>Casos de éxito</h2>
        </Reveal>
        <Reveal className="cases-head cases-head-solo">
          <div className="cases-nav">
            <button onClick={() => scrollBy(-1)} aria-label="Anterior"><ChevronLeft size={18} /></button>
            <button onClick={() => scrollBy(1)} aria-label="Siguiente"><ChevronRight size={18} /></button>
          </div>
        </Reveal>

        <div
          className="cases-scroller"
          ref={scrollerRef}
          onMouseEnter={() => setPaused(true)}
          onMouseLeave={() => setPaused(false)}
        >
          {CASES.map((c) => (
            <div key={c.client} className="case-card">
              <div className="case-img"><img src={CASE_IMG[c.client]} alt={c.client} loading="lazy" /></div>
              <div className="case-body">
                <span className="case-tag">{c.tag}</span>
                <h4>{c.client}</h4>
                <p className="case-headline">{c.headline}</p>
                <div className="case-metrics">
                  {c.metrics.map((m) => (<div key={m.l}><strong>{m.v}</strong><span>{m.l}</span></div>))}
                </div>
                <p className="case-note">{c.note}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

